 s("diebold.mariano","Comparing Predictive Accuracy","Diebold and Mariano","https://doi.org/10.1080/07350015.1995.10524599","comparative predictive accuracy requires an exact loss differential and dependence treatment","A statistical comparison is not selection or publication authority."),
 s("m4","The M4 Competition: Results, Findings, Conclusion and Way Forward","Makridakis et al.","https://doi.org/10.1016/j.ijforecast.2018.06.001","large heterogeneous series collections expose method rankings, combinations and baseline dependence","Competition rank does not prove fitness for a different population or purpose."),
 s("m5.accuracy","The M5 Accuracy Competition: Results, Findings and Conclusions","Makridakis et al.","https://doi.org/10.1016/j.ijforecast.2021.11.013","hierarchical retail evaluation uses exact scales, weights, horizons and baselines","A leaderboard is not operational selection governance."),
 s("m5.uncertainty","The M5 Uncertainty Competition: Results, Findings and Conclusions","Makridakis et al.","https://doi.org/10.1016/j.ijforecast.2021.10.005","quantile forecasts and uncertainty evaluation require level-, horizon- and hierarchy-specific scoring","Quantile competition results do not qualify every distributional forecast."),
